    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if (not (0 <= start[0] < rows and 0 <= start[1] < cols) or
        not (0 <= goal[0] < rows and 0 <= goal[1] < cols)):
        return []

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    from itertools import product

    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0

    changed = True
    while changed:
        changed = False
        for r, c in product(range(rows), range(cols)):
            if grid[r][c] == '#':
                continue
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if dist[r][c] > dist[nr][nc] + 1:
                        dist[r][c] = dist[nr][nc] + 1
                        changed = True

    if dist[goal[0]][goal[1]] == float('inf'):
        return []

    def backtrack(r, c):
        path = [(r, c)]
        while (r, c) != start:
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] + 1 == dist[r][c]:
                    r, c = nr, nc
                    path.append((r, c))
                    break
        return path[::-1]

    return backtrack(goal[0], goal[1])
