from collections import deque

def solve(grid, start, goal):
    def get_neighbors(cell):
        row, col = cell
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == '.':
                    yield (nr, nc)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    if (grid[start[0]][start[1]] == '#' or
        grid[goal[0]][goal[1]] == '#'):
        return []

    frontier = []
    counter = 0
    bisect.insort(frontier, (manhattan(start, goal), counter, start))
    visited = set([start])

    prev = {}
    while frontier:
        _, _, cell = frontier.pop(0)
        if cell == goal:
            path = []
            while cell in prev:
                path.append(cell)
                cell = prev[cell]
            path.append(start)
            return path[::-1]
        for next_cell in get_neighbors(cell):
            if next_cell not in visited:
                visited.add(next_cell)
                counter += 1
                bisect.insort(frontier, (manhattan(next_cell, goal), counter, next_cell))
                prev[next_cell] = cell
    return []
