        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    frontier = []
    heapq.heappush(frontier, (manhattan(start, goal), start))
    came_from = {}
    came_from[start] = None

    while frontier:
        current = heapq.heappop(frontier)[1]
        if current == goal:
            break
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            next_r, next_c = current[0] + dr, current[1] + dc
            if (0 <= next_r < rows and 0 <= next_c < cols and grid[next_r][next_c] == '.' and (next_r, next_c) not in came_from):
                came_from[(next_r, next_c)] = current
                priority = manhattan((next_r, next_c), goal)
                heapq.heappush(frontier, (priority, (next_r, next_c)))

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = came_from[current]
    return path[::-1]
