    grid_width = len(grid[0])
    dist = [[-1 for _ in range(grid_width)] for _ in range(grid_height)]

    dist[start[0]][start[1]] = 0

    d = 0
    while True:
        found = False
        for r in range(grid_height):
            for c in range(grid_width):
                if dist[r][c] == d:
                    for nr, nc in get_neighbors(r, c):
                        if dist[nr][nc] == -1:
                            dist[nr][nc] = d + 1
                            found = True
        if not found or d >= grid_height * grid_width:
            break
        d += 1

    if dist[goal[0]][goal[1]] == -1:
        return []

