            neighbor = (current[0] + dr, current[1] + dc)
            if neighbor not in visited and not is_wall(neighbor):
                if neighbor not in parent:
                    parent[neighbor] = current
                counter += 1
                heapq.heappush(pq, (-counter, neighbor))

