            # Reconstruct the path
            path = [goal]
            steps = [(r, c)]
            while steps[-1] != start:
                found = False
                for dr, dc in directions:
                    nr, nc = steps[-1][0] + dr, steps[-1][1] + dc
                    if 0 <= nr < rows and 0 <= nc < cols and closed[nr][nc]:
                        steps.append((nr, nc))
                        found = True
                        break
                if not found:
