def solve(grid, start, (goal_row, goal_col)):
    from collections import deque

    if grid[start[0]][start[1]] == '#' or grid[goal_row][goal_col] == '#':
        return []
    if start == (goal_row, goal_col):
        return [start]

    rows = len(grid)
    cols = len(grid[0])
    dist = [[float('inf')] * cols for _ in range(rows)]

    q = deque()
    q.append(start)
    dist[start[0]][start[1]] = 0

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if dist[nr][nc] == float('inf'):
                    dist[nr][nc] = dist[r][c] + 1
                    q.append((nr, nc))
                elif dist[nr][nc] > dist[r][c] + 1:
                    dist[nr][nc] = dist[r][c] + 1
                    q.appendleft((nr, nc))  # Reinsert at front for same level processing

    if dist[goal_row][goal_col] == float('inf'):
        return []

    # Reconstruct path
    path = []
    r, c = goal_row, goal_col
    while (r, c) != start:
        path.append((r, c))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and dist[nr][nc] == dist[r][c] - 1:
                r, c = nr, nc
                break
    path.append(start)
    path.reverse()
    return path
