def solve(grid, start, goal):
    def is_wall(r, c):
        return r < 0 or c < 0 or r >= len(grid) or c >= len(grid[0]) or grid[r][c] == '#'

    if is_wall(*start) or is_wall(*goal):
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    worklist = [start]
    dist = {start: 0}
    prev = {start: None}

    while worklist:
        cell = worklist.pop()
        current_dist = dist[cell]

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            r, c = cell[0] + dr, cell[1] + dc
            next_cell = (r, c)
            if is_wall(r, c):
                continue
            new_dist = current_dist + 1
            if next_cell not in dist or new_dist < dist[next_cell]:
                dist[next_cell] = new_dist
                prev[next_cell] = cell
                worklist.append(next_cell)

    if goal not in prev:
        return []

    path = []
    cell = goal
    while cell:
        path.append(cell)
        cell = prev[cell]
    path.reverse()
    return path
