        or not grid or not grid[0]
    ):
        if (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '#') or \
           (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '#'):
            return []
        return [start] if start == goal else []

