    dist = {}
    prev = {}
    worklist = []

    def relax(u, v):
        if v not in dist or dist[v] > dist[u] + 1:
            dist[v] = dist[u] + 1
            prev[v] = u
            heapq.heappush(worklist, (v[0], v[1]))

    dist[start] = 0
    heapq.heappush(worklist, (start[0], start[1]))

    while worklist:
        r, c = heapq.heappop(worklist)
        u = (r, c)
        if u == goal:
