import bisect

def solve(grid, start, goal):
    def is_wall(pos):
        r, c = pos
        return grid[r][c] == '#'

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0])

    if is_wall(start) or is_wall(goal):
        return []
    if start == goal:
        return [start]

    visited = set([start])
    frontier = [start]

    while frontier:
        current = frontier.pop(0)
        r, c = current

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited and not is_wall((nr, nc)):
                if (nr, nc) == goal:
                    return [start] + [current] + [(nr, nc)]
                bisect.insort(frontier, (nr, nc))
                visited.add((nr, nc))

    return []
