def solve(grid, start, goal):
    if (
        start[0] < 0 or start[0] >= len(grid) or start[1] < 0 or start[1] >= len(grid[0]) or
        goal[0] < 0 or goal[0] >= len(grid) or goal[1] < 0 or goal[1] >= len(grid[0])
    ):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    visited = set()
    frontier = [start]

    parent = {}
    parent[start] = None

    while frontier:
        current = frontier.pop(0)
        if current == goal:
            break
        if current in visited:
            continue
        visited.add(current)
        r, c = current

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if (
                0 <= nr < rows and 0 <= nc < cols and
                grid[nr][nc] == '.' and (nr, nc) not in visited
            ):
                if (nr, nc) not in parent:
                    parent[(nr, nc)] = current
                if (nr, nc) not in frontier:
                    bisect.insort(frontier, (nr, nc))

    if goal not in parent:
        return []

    path = []
    current = goal
    while current:
        path.append(current)
        current = parent[current]
    return path[::-1]
